mapper.select:
select a.code as menu_code, a.name, COALESCE(b.use_yn,'N') as use_yn, COALESCE(b.c_yn,'N') as c_yn, COALESCE(b.r_yn,'N') as r_yn, COALESCE(b.d_yn,'N') as d_yn from tb_menu a left outer join tb_menu_auth b on a.code = b.menucode where 1=1
and a.code = #{menu_code}
and b.role_id = #{role_id}

mapper.update:
update tb_menu_auth
   set c_yn = #{cYn}
      ,r_yn = #{rYn}
      ,d_yn = #{dYn}
      ,use_yn = #{useYn}
      ,update_by = #{updateBy}
      ,update_dt = NOW()
 where 1=1
   and menucode = #{menu_code}
   and role_id = #{role_id}

mapper.delete:
delete 
  from tb_menu_auth
 where 1=1
   and menucode = #{menu_code}
   and role_id = #{role_id}
